from pathlib import Path
p = Path('lib/ansible/config/base.yml')
s = p.read_text()
names = {'ANSIBLE_SSH_ARGS', 'ANSIBLE_SSH_CONTROL_PATH', 'ANSIBLE_SSH_CONTROL_PATH_DIR', 'ANSIBLE_SSH_EXECUTABLE', 'ANSIBLE_SSH_RETRIES', 'DEFAULT_SCP_IF_SSH', 'DEFAULT_SFTP_BATCH_MODE', 'DEFAULT_SSH_TRANSFER_METHOD'}
lines = s.splitlines(keepends=True)
start = None
removed = []
for i, line in enumerate(lines):
    if line.rstrip().endswith(':') and not line.startswith((' ', '\\t', '#')):
        name = line[:-2]
        if start is not None:
            removed.append((start, i))
            start = None
        if name in names:
            start = i
if start is not None:
    removed.append((start, len(lines)))
for a, b in reversed(removed):
    del lines[a:b]
p.write_text(''.join(lines))
print('Removed:', len(removed), [s.splitlines()[a] for a,b in removed])
